/// Bundled alert tones + a slot for a user-supplied file.
///
/// Each built-in entry exists twice: as a Flutter asset (previewed in app) and
/// as an Android `res/raw` resource (used by the notification channel). Both
/// files are generated by `tool/make_sounds.py`.
class SoundOption {
  const SoundOption({
    required this.id,
    required this.labelEn,
    required this.labelZh,
    required this.rawName,
    this.ext = 'wav',
    this.contentUri,
    this.localPath,
  });

  final String id;
  final String labelEn;
  final String labelZh;

  /// Name of the resource inside `android/app/src/main/res/raw`, without
  /// extension. Android derives the channel sound from this. Empty for a
  /// user-supplied tone.
  final String rawName;

  /// File extension of the bundled asset (`wav`, or `mp3` when the tone was
  /// supplied as an MP3).
  final String ext;

  /// `content://…` URI produced by the system media store for an uploaded
  /// tone. Only set for the [customSound] entry.
  final String? contentUri;

  /// Local copy of an uploaded tone, used for in-app preview.
  final String? localPath;

  bool get isCustom => contentUri != null || localPath != null;

  String get assetPath => 'assets/sounds/$rawName.$ext';

  String label(bool zh) => zh ? labelZh : labelEn;

  /// Android freezes a channel's audio the moment it is created, and Android 15
  /// and up *also* re-writes channels during an OS upgrade — which is how a
  /// channel ends up permanently silent. Bumping the suffix `v2` creates a fresh
  /// channel with the sound the user picked, instead of fighting a frozen one.
  static const String channelVersion = 'v2';

  /// Android caches channel audio, so the channel id must change whenever the
  /// chosen tone changes.
  String channelId() {
    if (isCustom) {
      final tail = (contentUri ?? localPath ?? '').split('/').last;
      return 'uk_alerts_custom_${tail}_$channelVersion';
    }
    return 'uk_alerts_${rawName}_$channelVersion';
  }

  static const List<SoundOption> all = [
    SoundOption(id: 'chime', labelEn: 'Soft chime', labelZh: '柔和钟声', rawName: 'alert_chime'),
    SoundOption(id: 'pulse', labelEn: 'Sharp pulse', labelZh: '短促脉冲', rawName: 'alert_pulse'),
    SoundOption(id: 'radar', labelEn: 'Radar sweep', labelZh: '雷达扫频', rawName: 'alert_radar'),
    SoundOption(id: 'marimba', labelEn: 'Marimba', labelZh: '木琴三音', rawName: 'alert_marimba'),
    SoundOption(id: 'siren', labelEn: 'Siren', labelZh: '警报笛', rawName: 'alert_siren'),
    SoundOption(
      id: 'ice',
      labelEn: 'Ice cubes 🧊',
      labelZh: '冰块 🧊',
      rawName: 'alert_ice',
      ext: 'mp3',
    ),
  ];

  static const String customId = 'custom';

  /// The uploaded tone, or null when the user has not installed one.
  static SoundOption? custom(String? contentUri, {String? localPath}) {
    final uri = (contentUri == null || contentUri.isEmpty) ? null : contentUri;
    final path = (localPath == null || localPath.isEmpty) ? null : localPath;
    if (uri == null && path == null) return null;
    return SoundOption(
      id: customId,
      labelEn: 'Uploaded tone',
      labelZh: '自定义提示音',
      rawName: '',
      ext: 'wav',
      contentUri: uri,
      localPath: path,
    );
  }

  static SoundOption byId(
    String? id, {
    String? customUri,
    String? customLocalPath,
  }) {
    if (id == customId) {
      final option = custom(customUri, localPath: customLocalPath);
      if (option != null) return option;
    }
    return all.firstWhere((s) => s.id == id, orElse: () => all.first);
  }
}
